"""Generate a brick's native CLI test script from its test cases."""

from __future__ import annotations

import shlex
from pathlib import Path
from typing import Any

import yaml

from brick_manager.errors import BrickManagerError
from brick_manager.identity import BrickSelector, validate_model_component


_TEST_CASES = Path("test/test_cases.yaml")
_SCRIPT_NAME = "run_tests.sh"
_GENERATED_MARKER = (
    "Generated by the Compute Flow Brick Manager from test/test_cases.yaml."
)


def write_test_script(
    install_path: Path, selector: BrickSelector, info_json: dict[str, Any]
) -> Path | None:
    """Write a test script for an installed brick when cases exist."""
    cases_path = install_path / _TEST_CASES
    if not cases_path.exists():
        return None
    if not cases_path.is_file():
        raise BrickManagerError(f"Test cases must be a file: {cases_path}")

    cases = _load_cases(cases_path, info_json["models"])
    script_path = cases_path.with_name(_SCRIPT_NAME)
    if script_path.exists() and (
        not script_path.is_file()
        or _GENERATED_MARKER not in script_path.read_text(encoding="utf-8")
    ):
        raise BrickManagerError(
            f"Generated test script path is already in use: {script_path}"
        )

    script_path.write_text(
        _render_script(selector, cases), encoding="utf-8", newline="\n"
    )
    return script_path


def _load_cases(
    cases_path: Path, declared_models: dict[str, Any]
) -> dict[str, dict[str, list[list[str]]]]:
    try:
        document = yaml.safe_load(cases_path.read_text(encoding="utf-8"))
    except (OSError, yaml.YAMLError) as error:
        raise BrickManagerError(
            f"Invalid test cases file: {cases_path}: {error}"
        ) from error

    if not isinstance(document, dict) or set(document) != {"models"}:
        raise BrickManagerError(
            f"Test cases must contain a models mapping: {cases_path}"
        )
    models = document["models"]
    if not isinstance(models, dict) or not models:
        raise BrickManagerError(
            f"Test cases models must be a non-empty mapping: {cases_path}"
        )

    cases: dict[str, dict[str, list[list[str]]]] = {}
    for model_name, manifests in models.items():
        if not isinstance(model_name, str) or model_name not in declared_models:
            raise BrickManagerError(
                f"Test model is not declared in info.json: {model_name}"
            )
        if not isinstance(manifests, dict) or not manifests:
            raise BrickManagerError(
                f"Test manifests must be a non-empty mapping: {model_name}"
            )

        model_cases: dict[str, list[list[str]]] = {}
        for manifest_name, manifest_cases in manifests.items():
            if not isinstance(manifest_name, str):
                raise BrickManagerError(f"Invalid test manifest name: {manifest_name}")
            validate_model_component("manifest", manifest_name)
            if not manifest_name.endswith(".json"):
                raise BrickManagerError(
                    f"Test manifest must be a JSON filename: {manifest_name}"
                )
            if not isinstance(manifest_cases, list) or not manifest_cases:
                raise BrickManagerError(
                    f"Test cases must be a non-empty list: {model_name}/{manifest_name}"
                )

            argument_lists: list[list[str]] = []
            for index, test_case in enumerate(manifest_cases):
                label = f"{model_name}/{manifest_name}[{index}]"
                if not isinstance(test_case, dict) or set(test_case) != {"args"}:
                    raise BrickManagerError(
                        f"Test case must contain only args: {label}"
                    )
                arguments = test_case["args"]
                if not isinstance(arguments, list) or any(
                    not isinstance(argument, str) for argument in arguments
                ):
                    raise BrickManagerError(f"Test case args must be strings: {label}")
                if "-m" in arguments:
                    raise BrickManagerError(f"Test case args must omit -m: {label}")
                argument_lists.append(arguments)
            model_cases[manifest_name] = argument_lists
        cases[model_name] = model_cases
    return cases


def _render_script(
    selector: BrickSelector, cases: dict[str, dict[str, list[list[str]]]]
) -> str:
    lines = [
        "#!/usr/bin/env bash",
        "#",
        "# SPDX-FileCopyrightText: Copyright 2026 Arm Limited and/or its affiliates <open-source-office@arm.com>",
        "#",
        "# SPDX-License-Identifier: Apache-2.0",
        "#",
        f"# {_GENERATED_MARKER}",
        "",
        "set -euo pipefail",
        "",
    ]

    for index, (model_name, manifests) in enumerate(cases.items()):
        model_dir = f"model_dir_{index}"
        uninstall_command = shlex.join(
            ["compute-flow", "model", "uninstall", selector.key, model_name]
        )
        lines.append(
            shlex.join(["compute-flow", "model", "install", selector.key, model_name])
        )
        lines.append(f"trap {shlex.quote(uninstall_command)} EXIT")
        model_path_command = shlex.join(
            ["compute-flow", "model", "path", selector.key, model_name]
        )
        lines.append(f"{model_dir}=$({model_path_command})")
        for manifest_name in manifests:
            message = shlex.quote(
                f"Manifest is not installed: {model_name}/{manifest_name}"
            )
            lines.extend(
                [
                    f'if [[ ! -f "${{{model_dir}}}/{manifest_name}" ]]; then',
                    f"  printf '%s\\n' {message} >&2",
                    "  exit 1",
                    "fi",
                ]
            )
        for manifest_name, argument_lists in manifests.items():
            manifest = f"@manifest/{selector.name}/{model_name}/{manifest_name}"
            for arguments in argument_lists:
                lines.append(
                    shlex.join(
                        [
                            "python",
                            "-m",
                            f"cli_examples.{selector.brick_type}_cli",
                            "-m",
                            manifest,
                            *arguments,
                        ]
                    )
                )
        lines.extend([uninstall_command, "trap - EXIT", ""])
    return "\n".join([*lines, ""])
